import heapq
import itertools

def match(orders):
    trades = []
    buy_heap = []  # entries: (-price, time, id)
    sell_heap = []  # entries: (price, time, id)
    order_info = {}  # id -> dict with side, price, qty, time, active
    counter = itertools.count()

    def add_to_book(oid):
        info = order_info[oid]
        t = next(counter)
        info['time'] = t
        if info['side'] == 'buy':
            heapq.heappush(buy_heap, (-info['price'], t, oid))
        else:
            heapq.heappush(sell_heap, (info['price'], t, oid))

    def top_valid_buy():
        while buy_heap:
            negprice, t, oid = buy_heap[0]
            info = order_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            return oid, info
        return None, None

    def top_valid_sell():
        while sell_heap:
            price, t, oid = sell_heap[0]
            info = order_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            return oid, info
        return None, None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = order_info.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        order_info[oid] = {'side': side, 'price': price, 'qty': remaining, 'time': None, 'active': True}

        if side == 'buy':
            while remaining > 0:
                sid, sinfo = top_valid_sell()
                if sid is None:
                    break
                if typ != 'market' and sinfo['price'] > price:
                    break
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, sid, sinfo['price'], trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                order_info[oid]['qty'] = remaining
                if sinfo['qty'] <= 0:
                    sinfo['active'] = False
                    heapq.heappop(sell_heap)
                # if partially filled, leave at top for next iteration check
                if remaining <= 0:
                    break
            order_info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                add_to_book(oid)
            else:
                order_info[oid]['active'] = False

        else:  # side == 'sell'
            while remaining > 0:
                bid, binfo = top_valid_buy()
                if bid is None:
                    break
                if typ != 'market' and binfo['price'] < price:
                    break
                trade_qty = min(remaining, binfo['qty'])
                trades.append([bid, oid, binfo['price'], trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                order_info[oid]['qty'] = remaining
                if binfo['qty'] <= 0:
                    binfo['active'] = False
                    heapq.heappop(buy_heap)
                if remaining <= 0:
                    break
            order_info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                add_to_book(oid)
            else:
                order_info[oid]['active'] = False

    return trades

